package com.spinplayer.app;
import android.content.Context;import android.graphics.*;import java.io.*;import java.net.*;
final class ArtworkCache {
 static File file(Context c,String raw){return new File(c.getFilesDir(),"art/online-"+Integer.toHexString(raw.hashCode())+".jpg");}
 static synchronized File load(Context c,String raw)throws Exception{String address=ArtworkUrl.allowed(raw);File dest=file(c,raw);if(dest.length()>0){BitmapFactory.Options cached=new BitmapFactory.Options();cached.inJustDecodeBounds=true;BitmapFactory.decodeFile(dest.getAbsolutePath(),cached);if(cached.outWidth>0&&cached.outHeight>0)return dest;dest.delete();}File dir=dest.getParentFile();dir.mkdirs();HttpURLConnection connection=NetDownloader.connect(address);File temp=null;long begin=System.nanoTime();String host=new URI(address).getHost();try{int status=connection.getResponseCode();AppDiagnostics.log(c,"ARTWORK_HTTP host="+host+" status="+status+" elapsed_ms="+(System.nanoTime()-begin)/1000000);if(status!=200)throw new IOException("ArtworkHttp"+status);byte[] data;try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>5*1024*1024)throw new IOException("ArtworkTooLarge");out.write(bytes,0,n);}data=out.toByteArray();}BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,o);if(o.outWidth<=0||o.outHeight<=0||o.outWidth>12000||o.outHeight>12000)throw new IOException("ArtworkInvalidImage");o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>900)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(data,0,data.length,o);if(bitmap==null)throw new IOException("ArtworkDecodeFailed");try{temp=File.createTempFile("online-",".part",dir);try(FileOutputStream out=new FileOutputStream(temp)){if(!bitmap.compress(Bitmap.CompressFormat.JPEG,90,out))throw new IOException("ArtworkEncodeFailed");}if(!temp.renameTo(dest)&&!dest.exists())throw new IOException("ArtworkCacheWriteFailed");}finally{bitmap.recycle();}try{CacheStorage.clean(c,false);}catch(Exception ignored){}return dest;}finally{connection.disconnect();if(temp!=null)temp.delete();}}
}
